def num_islands(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = set()
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1' and (r, c) not in visited:
                count += 1
                stack = [(r, c)]
                while stack:
                    x, y = stack.pop()
                    if 0 <= x < rows and 0 <= y < cols and (x, y) not in visited and grid[x][y] == '1':
                        visited.add((x, y))
                        stack.extend([(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)])
    return count
```

